import java.util.*;

public class Main {
    static List<Integer> topKFrequent(int[] numbers, int k) {
        Map<Integer, Integer> frequency = new HashMap<>();
        for (int n : numbers) frequency.merge(n, 1, Integer::sum);

        PriorityQueue<Map.Entry<Integer, Integer>> heap =
                new PriorityQueue<>(Comparator.comparingInt(Map.Entry::getValue));
        for (Map.Entry<Integer, Integer> entry : frequency.entrySet()) {
            heap.offer(entry);
            if (heap.size() > k) heap.poll();
        }

        List<Integer> result = new ArrayList<>();
        while (!heap.isEmpty()) result.add(heap.poll().getKey());
        Collections.reverse(result);
        return result;
    }

    public static void main(String[] args) {
        int[] numbers = {1, 1, 1, 2, 2, 3};
        System.out.println("Top 2: " + topKFrequent(numbers, 2));
    }
}

