public class Main {
    static class Node {
        int value; Node next;
        Node(int value) { this.value = value; }
    }

    static boolean hasCycle(Node head) {
        Node slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) return true;
        }
        return false;
    }

    public static void main(String[] args) {
        Node one = new Node(1), two = new Node(2), three = new Node(3);
        one.next = two; two.next = three; three.next = two;
        System.out.println("Cycle exists: " + hasCycle(one));
    }
}

import java.util.*;

public class Main {
    static int binarySearch(int[] numbers, int target) {
        int left = 0, right = numbers.length - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (numbers[mid] == target) return mid;
            if (numbers[mid] < target) left = mid + 1;
            else right = mid - 1;
        }
        return -1;
    }

    public static void main(String[] args) {
        int[] numbers = {1, 3, 5, 7, 9};
        int target = 7;
        System.out.println("Index: " + binarySearch(numbers, target));
    }
}

import java.util.*;

public class Main {
    static boolean isBalanced(String input) {
        Deque<Character> stack = new ArrayDeque<>();
        for (char c : input.toCharArray()) {
            if (c == '(' || c == '{' || c == '[') stack.push(c);
            else if (c == ')' || c == '}' || c == ']') {
                if (stack.isEmpty() || !matches(stack.pop(), c)) return false;
            }
        }
        return stack.isEmpty();
    }

    static boolean matches(char open, char close) {
        return (open == '(' && close == ')') ||
               (open == '{' && close == '}') ||
               (open == '[' && close == ']');
    }

    public static void main(String[] args) {
        String input = "{[()]}";
        System.out.println("Input: " + input);
        System.out.println("Balanced: " + isBalanced(input));
    }
}

