import java.util.*;

public class Main {
    static boolean isArmstrong(int n) {
        if (n < 0) return false;
        int original = n;
        int digits = String.valueOf(n).length();
        long sum = 0;
        int value = n;
        do {
            int digit = value % 10;
            sum += Math.pow(digit, digits);
            value /= 10;
        } while (value > 0);
        return sum == original;
    }

    public static void main(String[] args) {
        int n = 153;
        System.out.println(n + " is Armstrong: " + isArmstrong(n));
    }
}

