    static String removeDuplicates(String s) {
        Set<Character> seen = new LinkedHashSet<>();
        for (char c : s.toCharArray()) seen.add(c);
        StringBuilder result = new StringBuilder();
        for (char c : seen) result.append(c);
        return result.toString();
    }

    public static void main(String[] args) {
        String input = "programming";
        System.out.println("Output: " + removeDuplicates(input));
    }
}

import java.util.*;

public class Main {
    static Integer majority(int[] nums) {
        int candidate = 0, count = 0;
        for (int n : nums) {
            if (count == 0) candidate = n;
            count += n == candidate ? 1 : -1;
        }
        int frequency = 0;
        for (int n : nums) if (n == candidate) frequency++;
        return frequency > nums.length / 2 ? candidate : null;
    }

    public static void main(String[] args) {
        System.out.println("Majority: " + majority(new int[]{2,2,1,2,3,2,2}));
    }
}

import java.util.*;

public class Main {
    static int kthLargest(int[] nums, int k) {
        int target = nums.length - k;
        int left = 0, right = nums.length - 1;
        Random random = new Random(42);
        while (left <= right) {
            int pivotIndex = left + random.nextInt(right - left + 1);
            pivotIndex = partition(nums, left, right, pivotIndex);
            if (pivotIndex == target) return nums[pivotIndex];
            if (pivotIndex < target) left = pivotIndex + 1;
            else right = pivotIndex - 1;
        }
        throw new IllegalArgumentException("Invalid k");
    }

    static int partition(int[] a, int left, int right, int pivotIndex) {
        int pivot = a[pivotIndex];
        int t=a[pivotIndex]; a[pivotIndex]=a[right]; a[right]=t;
        int store=left;
        for(int i=left;i<right;i++) if(a[i]<pivot){ t=a[i];a[i]=a[store];a[store]=t;store++; }
        t=a[store];a[store]=a[right];a[right]=t;
        return store;
    }

    public static void main(String[] args) {
        System.out.println(kthLargest(new int[]{3,2,1,5,6,4}, 2));
    }
}

import java.util.*;

public class Main {
    static int longest(int[] nums) {
        Set<Integer> set = new HashSet<>();
        for (int n : nums) set.add(n);
        int best = 0;
        for (int n : set) {
            if (!set.contains(n - 1)) {
                int current = n;
                while (set.contains(current)) current++;
                best = Math.max(best, current - n);
            }
        }
        return best;
    }

    public static void main(String[] args) {
        System.out.println(longest(new int[]{100,4,200,1,3,2}));
    }
}

import java.util.*;

public class Main {
    static int[][] merge(int[][] intervals) {
        if (intervals.length == 0) return new int[0][];
        Arrays.sort(intervals, Comparator.comparingInt(a -> a[0]));
        List<int[]> result = new ArrayList<>();
        for (int[] current : intervals) {
            if (result.isEmpty() || result.get(result.size() - 1)[1] < current[0]) {
                result.add(current.clone());
            } else {
                int[] last = result.get(result.size() - 1);
                last[1] = Math.max(last[1], current[1]);
            }
        }
        return result.toArray(new int[0][]);
    }

    public static void main(String[] args) {
        int[][] result = merge(new int[][]{{1,3},{2,6},{8,10},{9,12}});
        for (int[] interval : result) System.out.println(Arrays.toString(interval));
    }
}

import java.util.*;

public class Main {
    static int longest(String s, int k) {
        if (k <= 0) return 0;
        Map<Character, Integer> freq = new HashMap<>();
        int left = 0, best = 0;
        for (int right = 0; right < s.length(); right++) {
            freq.merge(s.charAt(right), 1, Integer::sum);
            while (freq.size() > k) {
                char c = s.charAt(left++);
                int count = freq.get(c);
                if (count == 1) freq.remove(c); else freq.put(c, count - 1);
            }
            best = Math.max(best, right - left + 1);
        }
        return best;
    }

    public static void main(String[] args) {
        System.out.println(longest("eceba", 2));
    }
}

import java.util.*;

public class Main {
    static int findMin(int[] nums) {
        int left = 0, right = nums.length - 1;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] > nums[right]) left = mid + 1;
            else right = mid;
        }
        return nums[left];
    }

    public static void main(String[] args) {
        System.out.println(findMin(new int[]{4,5,6,7,0,1,2}));
    }
}

import java.util.*;

public class Main {
    static int[] range(int[] nums, int target) {
        return new int[]{bound(nums, target, true), bound(nums, target, false)};
    }
    static int bound(int[] a, int target, boolean first) {
        int left=0,right=a.length-1,answer=-1;
        while(left<=right){
            int mid=left+(right-left)/2;
            if(a[mid]==target){answer=mid;if(first)right=mid-1;else left=mid+1;}
            else if(a[mid]<target)left=mid+1;else right=mid-1;
        }
        return answer;
    }
    public static void main(String[] args){
        System.out.println(Arrays.toString(range(new int[]{1,2,2,2,3,4},2)));
    }
}

