public class Main {
    static class MinStack {
        private final Deque<Integer> values = new ArrayDeque<>();
        private final Deque<Integer> mins = new ArrayDeque<>();
        void push(int x) { values.push(x); if (mins.isEmpty() || x <= mins.peek()) mins.push(x); }
        int pop() { int x=values.pop(); if(x==mins.peek()) mins.pop(); return x; }
        int peek() { return values.peek(); }
        int min() { return mins.peek(); }
    }
    public static void main(String[] args){
        MinStack s=new MinStack(); s.push(5);s.push(3);s.push(7);s.push(2);
        System.out.println("Min: "+s.min()); s.pop(); System.out.println("Min: "+s.min());
    }
}

import java.util.*;

public class Main {
    static class Node { int value; Node left,right; Node(int value){this.value=value;} }
    static boolean contains(Node root, int target) {
        Node current=root;
        while(current!=null){
            if(current.value==target)return true;
            current = target < current.value ? current.left : current.right;
        }
        return false;
    }
    public static void main(String[] args){
        Node root=new Node(8);root.left=new Node(3);root.right=new Node(10);root.left.left=new Node(1);root.left.right=new Node(6);
        System.out.println(contains(root,6));
    }
}

import java.util.*;

public class Main {
    static class Node { int value; Node left,right; Node(int v){value=v;} }
    static void bfs(Node root) {
        if(root==null)return;
        Queue<Node> queue=new ArrayDeque<>(); queue.offer(root);
        while(!queue.isEmpty()){
            int size=queue.size();
            for(int i=0;i<size;i++){
                Node n=queue.poll(); System.out.print(n.value+(i+1==size?"\n":" "));
                if(n.left!=null)queue.offer(n.left); if(n.right!=null)queue.offer(n.right);
            }
        }
    }
    public static void main(String[] args){
        Node root=new Node(1);root.left=new Node(2);root.right=new Node(3);root.left.left=new Node(4);root.left.right=new Node(5);
        bfs(root);
    }
}

import java.util.*;

public class Main {
    static class Node { int value; Node next; Node(int v){value=v;} }
    static boolean hasCycle(Node head) {
        Node slow=head, fast=head;
        while(fast!=null && fast.next!=null){
            slow=slow.next; fast=fast.next.next;
            if(slow==fast)return true;
        }
        return false;
    }
    public static void main(String[] args){
        Node a=new Node(1),b=new Node(2),c=new Node(3); a.next=b;b.next=c;c.next=b;
        System.out.println("Cycle: "+hasCycle(a));
    }
}

import java.util.*;

public class Main {
    static class Node { int value; Node next; Node(int v){value=v;} }
    static Node middle(Node head) {
        Node slow=head, fast=head;
        while(fast!=null && fast.next!=null){ slow=slow.next; fast=fast.next.next; }
        return slow;
    }
    public static void main(String[] args){
        Node a=new Node(1),b=new Node(2),c=new Node(3),d=new Node(4),e=new Node(5);
        a.next=b;b.next=c;c.next=d;d.next=e;
        System.out.println("Middle: "+middle(a).value);
    }
}

import java.util.*;
import java.util.concurrent.locks.*;

public class Main {
    static class BoundedQueue<T> {
        private final Object[] items;
        private int head, tail, count;
        private final Lock lock = new ReentrantLock();
        private final Condition notFull = lock.newCondition();
        private final Condition notEmpty = lock.newCondition();
        BoundedQueue(int capacity){ items=new Object[capacity]; }
        void put(T value) throws InterruptedException {
            lock.lock();
            try { while(count==items.length) notFull.await(); items[tail]=value; tail=(tail+1)%items.length; count++; notEmpty.signal(); }
            finally { lock.unlock(); }
        }
        @SuppressWarnings("unchecked") T take() throws InterruptedException {
            lock.lock();
            try { while(count==0) notEmpty.await(); T value=(T)items[head]; items[head]=null; head=(head+1)%items.length; count--; notFull.signal(); return value; }
            finally { lock.unlock(); }
        }
    }
    public static void main(String[] args) throws Exception {
        BoundedQueue<Integer> q=new BoundedQueue<>(2); q.put(10);q.put(20);System.out.println(q.take());System.out.println(q.take());
    }
}

